  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
  START TRANSACTION;
  SELECT COUNT(*),MIN(id) INTO v_count,v_course FROM courses WHERE learning_language='en' AND base_language='fa';
  IF v_count=0 THEN INSERT INTO courses (learning_language,base_language,title,title_translation,description,description_translation,status,metadata) VALUES ('en','fa','English for Persian Speakers','انگلیسی برای فارسی‌زبانان','Independent story-first English course.','دورهٔ مستقل و داستان‌محور زبان انگلیسی.','active',JSON_OBJECT('contract','independent_course_v2','storyline','london_new_start')); SET v_course=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='en-fa course identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_level FROM levels WHERE course_id=v_course AND cefr_level='A1';
  IF v_count=0 THEN INSERT INTO levels (course_id,cefr_level,title,title_translation,description,description_translation,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_course,'A1','First Steps in English','نخستین گام‌ها در انگلیسی','Absolute-beginner English through Arman’s first days in London.','انگلیسی از صفر در داستان روزهای نخست آرمان در لندن.',1,2,1,'active',JSON_OBJECT('seriesStart',1,'seriesEnd',48)); SET v_level=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 level identity is not unique'; END IF;
  SELECT COUNT(*),MIN(id) INTO v_count,v_module FROM modules WHERE level_id=v_level AND sort_order=1;
  IF v_count=0 THEN INSERT INTO modules (level_id,title,title_translation,description,description_translation,emoji,difficulty_min,difficulty_max,sort_order,status,metadata) VALUES (v_level,'A New Start in London','شروعی تازه در لندن','Arman arrives and learns to handle his first conversations independently.','آرمان وارد لندن می‌شود و نخستین گفت‌وگوهای ضروری را مستقل انجام می‌دهد.','🧳',1,2,1,'active',JSON_OBJECT('storylineKey','london_new_start')); SET v_module=LAST_INSERT_ID(); ELSEIF v_count<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A1 module identity is not unique'; END IF;
